//! The per-plugin manifest: what a `.hsaco` contains, declared, hashed, and checkable.
//!
//! The manifest is generated by `saber-kbuild` from the code object it just built and then
//! committed next to the blob. At load time [`Manifest::validate_against_hsaco`] re-derives every
//! declared number from the blob and refuses on any mismatch -- including the blob's own sha256,
//! so a manifest can never describe a different build than the one it ships with.

use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use crate::abi::{pack, SigArg};
use crate::codeobj::CodeObject;
use crate::{Error, Result};

pub const SCHEMA_VERSION: u32 = 1;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ArgDecl {
    pub offset: u32,
    pub size: u32,
    pub value_kind: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct KernelDecl {
    pub name: String,
    pub symbol: String,
    pub kernarg_segment_size: u32,
    pub kernarg_segment_align: u32,
    pub group_segment_fixed_size: u32,
    pub private_segment_fixed_size: u32,
    pub vgpr_count: u32,
    pub sgpr_count: u32,
    pub wavefront_size: u32,
    pub max_flat_workgroup_size: u32,
    /// Only the explicit arguments; the HIP runtime fills the trailing `hidden_*` block.
    pub arg: Vec<ArgDecl>,
}

impl KernelDecl {
    /// Byte offset of the named argument, or `None` if this kernel has no such argument.
    pub fn arg_offset(&self, name: &str) -> Option<u32> {
        self.arg
            .iter()
            .find(|a| a.name.as_deref() == Some(name))
            .map(|a| a.offset)
    }

    /// Total size of the explicit argument block (what the host writes).
    pub fn explicit_kernarg_bytes(&self) -> u32 {
        self.arg
            .iter()
            .map(|a| a.offset + a.size)
            .max()
            .unwrap_or(0)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Manifest {
    pub schema_version: u32,
    /// Kernel-set stem, e.g. `mxfp4_gemm_decode`.
    pub plugin: String,
    pub arch: String,
    /// The source that was compiled, after the `<k>.gfx1201.hip -> <k>.gfx12.hip -> <k>.hip`
    /// override ladder, relative to the repo root.
    pub source: String,
    pub source_sha256: String,
    pub flags: String,
    /// sha256(preprocessed source ++ flags) — the build hash the autotune cache is keyed on.
    pub build_hash: String,
    pub hsaco: String,
    pub hsaco_sha256: String,
    pub kernel: Vec<KernelDecl>,
}

/// What `saber-kbuild` knows about a compile that the code object itself does not carry.
#[derive(Debug, Clone, Copy)]
pub struct BuildInfo<'a> {
    pub plugin: &'a str,
    pub arch: &'a str,
    /// Repo-relative path of the source that won the override ladder.
    pub source: &'a str,
    pub source_sha256: &'a str,
    pub flags: &'a str,
    /// sha256(preprocessed source ++ flags).
    pub build_hash: &'a str,
    pub hsaco_name: &'a str,
}

pub fn sha256_hex(bytes: &[u8]) -> String {
    let mut h = Sha256::new();
    h.update(bytes);
    hex::encode(h.finalize())
}

impl Manifest {
    pub fn load(path: impl AsRef<Path>) -> Result<Self> {
        let path = path.as_ref();
        let text = std::fs::read_to_string(path)?;
        let m: Manifest =
            toml::from_str(&text).map_err(|e| Error::Parse(format!("{}: {e}", path.display())))?;
        if m.schema_version != SCHEMA_VERSION {
            return Err(Error::Parse(format!(
                "{}: manifest schema {}, this build speaks {}",
                path.display(),
                m.schema_version,
                SCHEMA_VERSION
            )));
        }
        Ok(m)
    }

    pub fn save(&self, path: impl AsRef<Path>) -> Result<()> {
        let text = toml::to_string_pretty(self).map_err(|e| Error::Parse(e.to_string()))?;
        std::fs::write(path, text)?;
        Ok(())
    }

    pub fn kernel(&self, name: &str) -> Option<&KernelDecl> {
        self.kernel.iter().find(|k| k.name == name)
    }

    /// The blob this manifest describes, next to it on disk.
    pub fn hsaco_path(&self, dir: impl AsRef<Path>) -> PathBuf {
        dir.as_ref().join(&self.hsaco)
    }

    /// Build a manifest from a freshly compiled code object.
    pub fn from_code_object(b: &BuildInfo<'_>, hsaco_bytes: &[u8]) -> Result<Self> {
        let BuildInfo {
            plugin,
            arch,
            source,
            source_sha256,
            flags,
            build_hash,
            hsaco_name,
        } = b;
        let co = CodeObject::parse(hsaco_bytes)?;
        let mut kernel: Vec<KernelDecl> = co
            .kernels
            .iter()
            .map(|k| KernelDecl {
                name: k.name.clone(),
                symbol: k.symbol.clone(),
                kernarg_segment_size: k.kernarg_segment_size,
                kernarg_segment_align: k.kernarg_segment_align,
                group_segment_fixed_size: k.group_segment_fixed_size,
                private_segment_fixed_size: k.private_segment_fixed_size,
                vgpr_count: k.vgpr_count,
                sgpr_count: k.sgpr_count,
                wavefront_size: k.wavefront_size,
                max_flat_workgroup_size: k.max_flat_workgroup_size,
                arg: k
                    .explicit_args()
                    .map(|a| ArgDecl {
                        offset: a.offset,
                        size: a.size,
                        value_kind: a.value_kind.clone(),
                        name: a.name.clone(),
                    })
                    .collect(),
            })
            .collect();
        kernel.sort_by(|x, y| x.name.cmp(&y.name));
        // Name the arguments from the declared signature -- the code object has offsets but no
        // names -- and refuse a kernel whose layout does not pack the way that signature does.
        let mut bad = Vec::new();
        for k in &mut kernel {
            let Some(sig) = crate::abi::signature_for(&k.name) else {
                bad.push(format!("{}: no declared signature for this symbol", k.name));
                continue;
            };
            if sig.len() != k.arg.len() {
                bad.push(format!(
                    "{}: signature has {} args, code object {}",
                    k.name,
                    sig.len(),
                    k.arg.len()
                ));
                continue;
            }
            let (slots, _) = pack(sig);
            for (i, (s, (off, size))) in sig.iter().zip(slots).enumerate() {
                let a = &mut k.arg[i];
                if a.offset != off || a.size != size || a.value_kind != s.kind.value_kind() {
                    bad.push(format!(
                        "{}: arg {i} `{}` packs to (offset {off}, size {size}, {}) but the code \
                         object says (offset {}, size {}, {})",
                        k.name,
                        s.name,
                        s.kind.value_kind(),
                        a.offset,
                        a.size,
                        a.value_kind
                    ));
                }
                a.name = Some(s.name.to_owned());
            }
        }
        if !bad.is_empty() {
            return Err(Error::Validate(bad));
        }
        Ok(Manifest {
            schema_version: SCHEMA_VERSION,
            plugin: (*plugin).to_owned(),
            arch: (*arch).to_owned(),
            source: (*source).to_owned(),
            source_sha256: (*source_sha256).to_owned(),
            flags: (*flags).to_owned(),
            build_hash: (*build_hash).to_owned(),
            hsaco: (*hsaco_name).to_owned(),
            hsaco_sha256: sha256_hex(hsaco_bytes),
            kernel,
        })
    }

    /// Refuse unless every declared number is what the code object itself reports.
    ///
    /// This is the "partition-mismatched tuple silently hangs the GPU" hazard made structural: the
    /// host's idea of the kernarg layout, the LDS size, the wave size and the register counts must
    /// come out of the blob it is about to launch, not out of a header that drifted.
    pub fn validate_against_hsaco(&self, hsaco_bytes: &[u8]) -> Result<()> {
        let mut bad: Vec<String> = Vec::new();
        let actual = sha256_hex(hsaco_bytes);
        if actual != self.hsaco_sha256 {
            bad.push(format!(
                "{}: blob sha256 {} but manifest declares {}",
                self.hsaco, actual, self.hsaco_sha256
            ));
            // Everything below would be describing a different build; say so once and stop.
            return Err(Error::Validate(bad));
        }
        let co = CodeObject::parse(hsaco_bytes)?;
        if !co.target.contains(&self.arch) {
            bad.push(format!("target `{}` is not {}", co.target, self.arch));
        }
        for d in &self.kernel {
            let Some(k) = co.kernel(&d.name) else {
                bad.push(format!("{}: not in the code object", d.name));
                continue;
            };
            let mut cmp = |field: &str, want: u32, got: u32| {
                if want != got {
                    bad.push(format!(
                        "{}: {field} declared {want}, code object {got}",
                        d.name
                    ));
                }
            };
            cmp(
                "kernarg_segment_size",
                d.kernarg_segment_size,
                k.kernarg_segment_size,
            );
            cmp(
                "kernarg_segment_align",
                d.kernarg_segment_align,
                k.kernarg_segment_align,
            );
            cmp(
                "group_segment_fixed_size",
                d.group_segment_fixed_size,
                k.group_segment_fixed_size,
            );
            cmp(
                "private_segment_fixed_size",
                d.private_segment_fixed_size,
                k.private_segment_fixed_size,
            );
            cmp("vgpr_count", d.vgpr_count, k.vgpr_count);
            cmp("sgpr_count", d.sgpr_count, k.sgpr_count);
            cmp("wavefront_size", d.wavefront_size, k.wavefront_size);
            cmp(
                "max_flat_workgroup_size",
                d.max_flat_workgroup_size,
                k.max_flat_workgroup_size,
            );
            if d.symbol != k.symbol {
                bad.push(format!(
                    "{}: symbol declared `{}`, code object `{}`",
                    d.name, d.symbol, k.symbol
                ));
            }
            let got: Vec<_> = k.explicit_args().collect();
            if got.len() != d.arg.len() {
                bad.push(format!(
                    "{}: {} explicit args declared, code object has {}",
                    d.name,
                    d.arg.len(),
                    got.len()
                ));
                continue;
            }
            for (i, (want, have)) in d.arg.iter().zip(got).enumerate() {
                if want.offset != have.offset
                    || want.size != have.size
                    || want.value_kind != have.value_kind
                {
                    bad.push(format!(
                        "{}: arg {i} declared (offset {}, size {}, {}) but the code object says \
                         (offset {}, size {}, {})",
                        d.name,
                        want.offset,
                        want.size,
                        want.value_kind,
                        have.offset,
                        have.size,
                        have.value_kind
                    ));
                }
            }
        }
        if bad.is_empty() {
            Ok(())
        } else {
            Err(Error::Validate(bad))
        }
    }

    /// Refuse unless the kernel's kernarg layout is exactly what `sig` packs to.
    ///
    /// The code object gives offsets but not meaning; this binds the host's *named* operands to
    /// them. Called by `resolve`'s consumers before a launch is built.
    pub fn check_signature(&self, kernel: &str, sig: &[SigArg]) -> Result<()> {
        let k = self
            .kernel(kernel)
            .ok_or_else(|| Error::Rule(format!("{}: no kernel `{kernel}`", self.plugin)))?;
        let (slots, size) = pack(sig);
        let mut bad = Vec::new();
        if k.arg.len() != sig.len() {
            bad.push(format!(
                "{kernel}: signature has {} args, manifest {}",
                sig.len(),
                k.arg.len()
            ));
        } else {
            for (i, (s, (off, sz))) in sig.iter().zip(slots).enumerate() {
                let d = &k.arg[i];
                if d.offset != off || d.size != sz || d.value_kind != s.kind.value_kind() {
                    bad.push(format!(
                        "{kernel}: arg {i} `{}` packs to (offset {off}, size {sz}, {}) but the \
                         manifest says (offset {}, size {}, {})",
                        s.name,
                        s.kind.value_kind(),
                        d.offset,
                        d.size,
                        d.value_kind
                    ));
                }
            }
            if size > k.kernarg_segment_size {
                bad.push(format!(
                    "{kernel}: explicit args need {size} B, kernarg segment is {} B",
                    k.kernarg_segment_size
                ));
            }
        }
        if bad.is_empty() {
            Ok(())
        } else {
            Err(Error::Validate(bad))
        }
    }
}

/// Load every committed plugin manifest and validate it against its blob.
pub fn load_prebuilt() -> Result<Vec<(Manifest, Vec<u8>)>> {
    let dir = crate::prebuilt::dir();
    let mut out = Vec::new();
    for (blob, _) in crate::prebuilt::ALL {
        let stem = blob.trim_end_matches(".hsaco");
        let m = Manifest::load(dir.join(format!("{stem}.manifest.toml")))?;
        let bytes = std::fs::read(m.hsaco_path(&dir))?;
        m.validate_against_hsaco(&bytes)?;
        out.push((m, bytes));
    }
    Ok(out)
}
